    'data_science-data_engineering-s1-set1' => [
        [
            'text' => 'Explain the distributed execution architecture of Apache Spark. Detail the roles of the Spark Driver, Cluster Manager, Executors, Tasks, and Slots. What is the fundamental difference between Transformations (lazy evaluation) and Actions (e.g. count, collect)?',
